const { chromium } = require("playwright");
const path = require("path");
const fs = require("fs");
const axeSrc = fs.readFileSync("/tmp/axe.min.js", "utf8");

const htmlFile = path.resolve(
  "/workspace/sandbox/skills/building-accessible-ui/modal-dialog--framework-react--style-dark/claude-sonnet-4.6__s2/index.html"
);

(async () => {
  const b = await chromium.launch();
  const page = await b.newPage();

  // Load the page
  await page.goto("file://" + htmlFile, { waitUntil: "load" });
  await page.addScriptTag({ path: "/tmp/axe.min.js" });

  // Run axe on default (closed dialog) state
  const r1 = await page.evaluate("async () => await window.axe.run()");

  // Open the dialog and re-run
  await page.click(".trigger");
  await page.waitForSelector("dialog[open]");
  const r2 = await page.evaluate("async () => await window.axe.run()");

  await b.close();

  const format = (v) => ({
    id: v.id,
    impact: v.impact,
    tags: v.tags.filter(t => t.startsWith("wcag") || t === "best-practice"),
    targets: v.nodes.map(n => n.target),
    help: v.help,
  });

  const all = [...r1.violations, ...r2.violations];
  const seen = new Set();
  const deduped = all.filter(v => { const k = v.id; if (seen.has(k)) return false; seen.add(k); return true; });

  const wcag = deduped.filter(v => !v.tags.includes("best-practice"));
  const bp   = deduped.filter(v =>  v.tags.includes("best-practice"));

  console.log("=== WCAG VIOLATIONS ===");
  console.log(JSON.stringify(wcag.map(format), null, 2));
  console.log("=== BEST PRACTICE ===");
  console.log(JSON.stringify(bp.map(format), null, 2));
  process.exit(wcag.length > 0 ? 1 : 0);
})();
EOF
